contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint withdrawAmount, address target, uint sendAmount) public payable {
        // amount is Ether sent into C via fallback; withdrawAmount and sendAmount must not exceed C's balance.
        require(address(this).balance >= amount);

        // Initial public state of C, observed before any mutating call.
        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        // Send Ether to C through the fallback: must increase depositsCount by exactly 1.
        (bool fallbackOk, ) = address(c).call{value: amount}("");
        require(fallbackOk);
        uint depositsAfterFallback = c.depositsCount();
        uint cBalanceAfterFallback = address(c).balance;

        // OnlyOwner withdrawal: amount is limited to the balance C now holds.
        require(withdrawAmount <= cBalanceAfterFallback);
        if (withdrawAmount > 0) {
            c.withdraw(withdrawAmount);
        }

        uint cBalanceAfterWithdraw = address(c).balance;

        // OnlyOwner sendMoney: amount is limited to the balance C now holds.
        require(sendAmount <= cBalanceAfterWithdraw);
        if (sendAmount > 0) {
            c.sendMoney(target, sendAmount);
        }

        uint cBalanceFinal = address(c).balance;

        assert(
            depositsAfterFallback == depositsBefore + 1 &&
            depositsAfterFallback == c.depositsCount() &&
            cBalanceAfterFallback == cBalanceBefore + amount &&
            cBalanceAfterWithdraw == cBalanceAfterFallback - withdrawAmount &&
            cBalanceFinal == cBalanceAfterWithdraw - sendAmount
        );
    }

    receive() external payable {}
}

