contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        assert(
            (beforeCount > 0 || msg.sender == c.owner())
                ? afterCount == beforeCount + 1
                : afterCount == beforeCount
        );
        assert(
            !reverted
                ? address(c).balance == beforeBal + amount
                : address(c).balance == beforeBal
        );
    }

    receive() external payable {}
}

